import{_ as e,a as r,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 63 既济：完成之后仍要照料至读完六十四卦之后","description":"从巽兑的沟通读到涣节的尺度、中孚的信实与既济未济的开放结尾，逐爻核对古籍。","frontmatter":{"title":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 63 既济：完成之后仍要照料至读完六十四卦之后","description":"从巽兑的沟通读到涣节的尺度、中孚的信实与既济未济的开放结尾，逐爻核对古籍。","splitFrom":"life/personal/yijing/hexagrams-57-64.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济","summary":"从巽兑的沟通读到涣节的尺度、中孚的信实与既济未济的开放结尾，逐爻核对古籍。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 60 节：尺度应使生活可持续至62 小过：在有限处适度加厚","link":"/life/personal/yijing/hexagrams-57-64-part-02"},"next":{"text":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 60 节：尺度应使生活可持续至62 小过：在有限处适度加厚","link":"/life/personal/yijing/hexagrams-57-64-part-02"},"next":{"text":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-57-64-part-03.md","filePath":"life/personal/yijing/hexagrams-57-64-part-03.md"}'),o={name:"life/personal/yijing/hexagrams-57-64-part-03.md"};function d(i,t,s,l,p,g){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读-五十七至六十四-巽、兑、涣、节、中孚、小过、既济、未济-·-63-既济-完成之后仍要照料至读完六十四卦之后" tabindex="-1">六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 63 既济：完成之后仍要照料至读完六十四卦之后 <a class="header-anchor" href="#六十四卦详读-五十七至六十四-巽、兑、涣、节、中孚、小过、既济、未济-·-63-既济-完成之后仍要照料至读完六十四卦之后" aria-label="Permalink to &quot;六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 63 既济：完成之后仍要照料至读完六十四卦之后&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-57-64">返回分篇目录</a></p><p>本篇完成六十四卦的最后一组。每卦先列<strong>经文原文</strong>，再列现代简释；<strong>大象</strong>来自《象传》，主要古注依据为王弼注、孔颖达疏《周易正义》。引文保留古代字形与占筮判断，现代概括不作为预测方法。个别电子本文字不同，采用哪种写法会就地注明。</p><p>这组可从四条线索进入：巽与兑的传达和相悦，涣与节的散释和限制，中孚与小过的信实和分寸，既济与未济的完成和未完成。不要先给整卦贴上“好卦、坏卦”标签，再忽略其中相反的爻辞。</p><h2 id="gua-63" tabindex="-1">63 既济：完成之后仍要照料 <a class="header-anchor" href="#gua-63" aria-label="Permalink to &quot;63 既济：完成之后仍要照料 {#gua-63}&quot;">​</a></h2><p><strong>卦符：䷾｜上卦坎 ☵（水），下卦离 ☲（火）。</strong> 水在火上可成烹饪；六爻阴阳各得其位，传注以此说明暂时配合齐备。</p><p><strong>卦辞原文：</strong></p><blockquote><p>既濟：亨小。利貞。初吉終亂。</p></blockquote><p><strong>白话概括：</strong> 已经渡过、事情获得完成，但仍需正当维持，否则初吉之后可能生乱。“亨小”的断句、释义有讨论，《正义》重在连小者也得通达。古注明确说终乱“由止故乱”，不是宣布一切完成都命定失败。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>曳其輪，濡其尾，无咎。</td><td>车轮拖曳，尾部沾湿，渡水之初仍有不稳；古注从初济尚未到干地解释，不因总体已济就抹去局部困难。</td></tr><tr><td>六二</td><td>婦喪其茀，勿逐，七日得。</td><td>女子失去茀，不必急追而后可复得；“茀”古注释首饰，亦有车蔽等解释，七日不作现实寻物保证。</td></tr><tr><td>九三</td><td>高宗伐鬼方，三年克之，小人勿用。</td><td>以高宗征伐的长期艰苦说明完成并不轻松；古注认作商王武丁，不能据经文单独重建全部战史。</td></tr><tr><td>六四</td><td>繻有衣袽，終日戒。</td><td>备有旧絮补漏，终日警戒；王注认为“繻”应作“濡”，以舟漏说明预备，保留原字并注明校读。</td></tr><tr><td>九五</td><td>東鄰殺牛，不如西鄰之禴祭，實受其福。</td><td>丰厚祭品不如合时而真诚的简祭；效果不能只靠投入规模衡量，东西也不宜直接当作趋吉方位。</td></tr><tr><td>上六</td><td>濡其首，厲。</td><td>已经湿到头部，处境危险；若只顾继续推进而不察界限，完成也可能转成新的困境。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>水在火上，既濟；君子以思患而豫防之。</p></blockquote><p><strong>大象解释：</strong> 事情已成，仍考虑潜在问题并预作防备。“豫”通预；这是一种维护意识，不是要求持续灾难想象。</p><p><strong>整体读法与误区：</strong> 既济是六十四卦中最容易被“吉卦”标签误导的一卦：位置整齐，爻辞却有失物、战争、补漏和濡首。现代可借来讨论交付后的维护、关系建立后的经营或学习阶段完成后的应用。只庆祝成果而没有后续照料，才是“终止则乱”所警惕的方向。反过来，适当休息不等于停止一切维护，不能用此卦制造永不休息的压力。</p><p><strong>经传对读：</strong> 卦辞说“终乱”，九五仍能受福，说明总体警戒不取消具体爻位的条件。初爻湿尾与上爻湿首形成程度差别，六四的衣袽则把防患变成可操作的补漏准备。九三还提醒成功所耗费的时间和人力，所以讨论完成时，应同时记住成果、成本和余留风险，而非只留下胜利叙事。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F" target="_blank" rel="noopener noreferrer">《周易·既济》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/06%E6%97%A2%E6%BF%9F" target="_blank" rel="noopener noreferrer">《周易正义》卷六·既济</a>。</p><h2 id="gua-64" tabindex="-1">64 未济：未完成仍有可成之理 <a class="header-anchor" href="#gua-64" aria-label="Permalink to &quot;64 未济：未完成仍有可成之理 {#gua-64}&quot;">​</a></h2><p><strong>卦符：䷿｜上卦离 ☲（火），下卦坎 ☵（水）。</strong> 火在水上而各趋其向，尚未形成既济的配合；六爻虽皆不当位，阴阳仍相应，这是《彖传》留下通达可能的依据。</p><p><strong>卦辞原文：</strong></p><blockquote><p>未濟：亨。小狐汔濟，濡其尾，无攸利。</p></blockquote><p><strong>白话概括：</strong> 尚未渡成仍可通达，但小狐渡水而尾湿，暴露出续终力量不足。“汔”可按几、将近理解；《正义》另从水将尽、狐待浅水解释，二者在取象上不同。古注共同关注的是不能只看开始，还要有完成所需的余力。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>濡其尾，吝。</td><td>尚处险中而贸进，尾已沾湿，显出不知限度；需重新判断条件，不能只凭急切愿望渡险。</td></tr><tr><td>九二</td><td>曳其輪，貞吉。</td><td>拖曳其轮而守正，古注把重点放在居中、以刚健助难；常见读法也重审慎行进，不能只据字形判停或走。</td></tr><tr><td>六三</td><td>未濟，征凶，利涉大川。</td><td>独力前进凶，却又利渡大川；《正义》以自己不足、借九二相助来解释两句条件之别。</td></tr><tr><td>九四</td><td>貞吉，悔亡，震用伐鬼方，三年有賞于大國。</td><td>正志而行、长期承担艰难，才有受赏；征伐属于古代政治叙事，不宜移成对现实对手的战争思维。</td></tr><tr><td>六五</td><td>貞吉，无悔，君子之光，有孚，吉。</td><td>以正当、信任和明德居中，古注强调委任有能力者；领导的作用不必表现为所有事情亲自做。</td></tr><tr><td>上九</td><td>有孚于飲酒，无咎，濡其首，有孚失是。</td><td>相信伙伴而饮酒可无过，沉溺到濡首就失去分寸；最后仍有节制警戒，而非大功告成后的无限纵乐。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>火在水上，未濟；君子以慎辨物居方。</p></blockquote><p><strong>大象解释：</strong> 仔细辨别事物及其合适位置，先建立可相互配合的安排。古注所说“各当其所”，今天可转成角色、资源和条件的恰当配置，但须避免把人的社会位置永久固定。</p><p><strong>整体读法与误区：</strong>《正义》说称“未济”而不称“不济”，因为尚有相助、可济之理。全书以未济结束，读者可以由此思考变化仍会继续；这是依据篇章结构的阅读，不是永恒循环的科学定律。现代面对未完成事项，可区分目标不清、能力不足、合作未成和收尾缺力，分别处理；不能把“尚有可能”误作“只要坚持必然成功”。</p><p><strong>经传对读：</strong> 既济初九与未济九二同见曳轮，两卦上爻又都写濡首，但各自的上下文与占断不同。相同意象可以提示联系，却不能代替逐句分析。未济六三的征凶与利涉并列，尤其适合练习寻找隐含条件：独力硬进与借助适当伙伴并非同一行动；条件改变以后，判断才可能随之改变。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%9C%AA%E6%BF%9F" target="_blank" rel="noopener noreferrer">《周易·未济》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/06%E6%9C%AA%E6%BF%9F" target="_blank" rel="noopener noreferrer">《周易正义》卷六·未济</a>。</p><h2 id="读完六十四卦之后" tabindex="-1">读完六十四卦之后 <a class="header-anchor" href="#读完六十四卦之后" aria-label="Permalink to &quot;读完六十四卦之后 {#读完六十四卦之后}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>比较对象</th><th>值得反复追问的问题</th></tr></thead><tbody><tr><td>巽九二与上九</td><td>同样“巽在床下”，为什么判断不同？姿态之外还缺哪些条件？</td></tr><tr><td>节初九与九二</td><td>同样不出庭，什么时候是审慎，什么时候是失时？</td></tr><tr><td>中孚九二与上九</td><td>有回应的信实与高扬的声名，如何从行动中辨别？</td></tr><tr><td>既济与未济</td><td>什么算完成？完成后要维护什么？未完成还缺哪一项真实条件？</td></tr></tbody></table><p>可以任选一组，把经文意象、传文解释、古注意见、自己的现代应用分成四栏书写。若四栏中出现同一句话，检查是否把后人的解释误认成经文原意。阅读的收获是更精细地分辨处境，而不是把六十四卦变成六十四条固定命运。</p><p>返回 <a href="/life/personal/yijing/overview">易经专题导读</a>。</p>',34)])])}const u=e(o,[["render",d]]);export{c as __pageData,u as default};
